// service (svc.bal):
import ballerina/http;

final http:Client backend = check new ("http://127.0.0.1:19701", {httpVersion: http:HTTP_1_1});

service / on new http:Listener(19702) {
    resource function get textNoRead() returns http:Response|error {
        http:Response res = check backend->get("/big");
        res.setTextPayload("hello");
        return res;
    }

    resource function get textAfterRead() returns http:Response|error {
        http:Response res = check backend->get("/big");
        _ = check res.getTextPayload();
        res.setTextPayload("hello");
        return res;
    }
}

// client (client.bal):
import ballerina/http;
import ballerina/io;

public function main() returns error? {
    http:Client c = check new ("http://127.0.0.1:19702", {httpVersion: http:HTTP_1_1, timeout: 10});
    foreach string p in ["/textNoRead", "/textAfterRead"] {
        http:Response r = check c->get(p);
        string|error body = r.getTextPayload();
        io:println(p, " cl=", check r.getHeader("content-length"), " body=[", body is string ? body : "ERR:" + body.message(), "]");
    }
}

